import { NextResponse } from 'next/server';

type PostPayload = {
  title?: string;
  content?: string;
};

type Post = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
};

type RouteContext = {
  params: {
    id: string;
  };
};

function parseId(id: string): number | null {
  const value = Number(id);
  return Number.isNaN(value) ? null : value;
}

export async function GET(request: Request, { params }: RouteContext) {
  const postId = parseId(params.id);

  if (postId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post: Post = {
    id: postId,
    title: "'`Post ${params.id}`,
    content: `This is the content for post ${params.id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post, { status: 200 });
}

export async function PUT(request: Request, { params }: RouteContext) {
  const postId = parseId(params.id);

  if (postId === null) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  let body: PostPayload;

  try {
    body = (await request.json()) as PostPayload;
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON payload' },
      { status: 400 }
    );
  }

  const updatedPost: Post = {
    id: postId,
    title: body.title ?? "'`Post ${params.id}`,
    content: body.content ?? `Updated content for post ${params.id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost, { status: 200 });
}

export async function DELETE(request: Request, { params }: RouteContext) {
  const postId = parseId(params.id);

  if (postId === null) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json(
    { message: "'`Post ${params.id} deleted successfully` },
    { status: 200 }
  );
}
EOF'
